class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def imgMultiply(root):
    MOD = 10**9 + 7

    def dfs(node1, node2):
        if not node1 and not node2:
            return 0
        if not node1 or not node2:
            return 0
        return (node1.val * node2.val + dfs(node1.left, node2.right) + dfs(node1.right, node2.left)) % MOD

    return dfs(root, root)

import sys
from collections import deque

def build_tree(nodes, f):
    if not nodes:
        return None
    root = TreeNode(int(next(f).strip()))
    q = deque([root])
    while q:
        current = q.popleft()
        left_val = next(f).strip()
        right_val = next(f).strip()
        if left_val != 'null':
            current.left = TreeNode(int(left_val))
            q.append(current.left)
        if right_val != 'null':
            current.right = TreeNode(int(right_val))
            q.append(current.right)
    return root

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    root = build_tree(data, iter(data))
    print(imgMultiply(root))
